export type CssAccordion01Props = AuthorizedPortProps;

export const CssAccordion01 = forwardRef<
  HTMLIFrameElement,
  CssAccordion01Props
>(function CssAccordion01(props, ref) {
  return (
    <AuthorizedPortFrame
      {...props}
      ref={ref}
      slug="css-accordion01"
      title={props.title ?? "accordion 1"}
    />
  );
});

